      const data = await response.json();

      if (!response.ok) {
        setError('Invalid email or password');
        return;
      }

      if (data.mfaRequired) {
        // MFA is enabled - proceed to second step
        setMfaToken(data.mfaToken);
        setStep('mfa');
      } else {
        // No MFA - login complete
        window.location.href = '/dashboard';
      }
    } catch (err) {
      setError('An error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleMFASubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      const response = await fetch('/api/auth/verify-mfa', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ 
          mfaToken, 
          code: mfaCode,
        }),
      });

      if (!response.ok) {
        setError('Invalid code. Please try again.');
        return;
      }

      // MFA verified - login complete
      window.location.href = '/dashboard';
    } catch (err) {
      setError('Verification failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  if (step === 'mfa') {
    return (
      <form onSubmit={handleMFASubmit} className="mfa-form">
        <h2>Two-Factor Authentication</h2>
        <p>Enter the code from your authenticator app</p>

        <input
          type="text"
          inputMode="numeric"
          pattern="[0-9]{6}"
          maxLength={6}
          value={mfaCode}
          onChange={(e) => setMfaCode(e.target.value.replace(/\D/g, ''))}
          autoComplete="one-time-code"
          placeholder="000000"
          autoFocus
        />

        {error && <p className="error" role="alert">{error}</p>}

        <button type="submit" disabled={isLoading || mfaCode.length !== 6}>
          {isLoading ? 'Verifying...' : 'Verify'}
        </button>

        <button 
          type="button" 
          className="link-button"
          onClick={() => setStep('backup')}
        >
          Use a backup code instead
        </button>
      </form>
    );
  }

  return (
    <form onSubmit={handleCredentialsSubmit} className="login-form">
      <h2>Log In</h2>

      <label>
        Email
        <input
          type="email"
          value={credentials.email}
          onChange={(e) => setCredentials({...credentials, email: e.target.value})}
          autoComplete="email"
          required
        />
      </label>

      <label>
        Password
        <input
          type="password"
          value={credentials.password}
          onChange={(e) => setCredentials({...credentials, password: e.target.value})}
          autoComplete="current-password"
          required
        />
      </label>

      {error && <p className="error" role="alert">{error}</p>}

      <button type="submit" disabled={isLoading}>
        {isLoading ? 'Logging in...' : 'Log In'}
      </button>
    </form>
  );
}
```

### **Server-Side Login with MFA**

```javascript
// Step 1: Verify credentials
app.post('/api/auth/login', async (req, res) => {
  const { email, password } = req.body;

  // Verify credentials
  const user = await verifyCredentials(email, password);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Check if MFA is enabled
  if (user.mfaEnabled) {
    // Generate temporary MFA token (short-lived, single-use)
    const mfaToken = jwt.sign(
      { userId: user.id, purpose: 'mfa' },
      process.env.MFA_TOKEN_SECRET,
      { expiresIn: '5m' }
    );

    return res.json({ 
      mfaRequired: true, 
      mfaToken,
    });
  }

  // No MFA - complete login
  await createSession(res, user);
  res.json({ success: true });
});

// Step 2: Verify MFA code
app.post('/api/auth/verify-mfa', async (req, res) => {
  const { mfaToken, code } = req.body;

  // Verify MFA token
  let payload;
  try {
    payload = jwt.verify(mfaToken, process.env.MFA_TOKEN_SECRET);
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired MFA session' });
  }

  if (payload.purpose !== 'mfa') {
    return res.status(401).json({ error: 'Invalid token' });
  }

  const user = await getUserById(payload.userId);

  // Verify TOTP code
  const verified = speakeasy.totp.verify({
    secret: user.mfaSecret,
    encoding: 'base32',
    token: code,
    window: 1,
  });

  if (!verified) {
    // Check if it's a backup code
    const backupCodeValid = await verifyBackupCode(user.id, code);
    if (!backupCodeValid) {
      return res.status(401).json({ error: 'Invalid code' });
    }
  }

  // MFA verified - complete login
  await createSession(res, user);
  res.json({ success: true });
});
