### **Server-Side WebAuthn (Node.js)**

```javascript
const {
  generateRegistrationOptions,
  verifyRegistrationResponse,
  generateAuthenticationOptions,
  verifyAuthenticationResponse,
} = require('@simplewebauthn/server');

const rpName = 'Your App';
const rpID = 'yourapp.com';
const origin = 'https://yourapp.com';

// Registration options
app.post('/api/webauthn/register-options', authenticate, async (req, res) => {
  const user = req.user;
  const userAuthenticators = await getUserAuthenticators(user.id);

  const options = await generateRegistrationOptions({
    rpName,
    rpID,
    userID: user.id,
    userName: user.email,
    attestationType: 'none',
    excludeCredentials: userAuthenticators.map(auth => ({
      id: auth.credentialID,
      type: 'public-key',
    })),
    authenticatorSelection: {
      residentKey: 'preferred',
      userVerification: 'preferred',
    },
  });

  // Store challenge for verification
  await storeChallenge(user.id, options.challenge);

  res.json(options);
});

// Verify registration
app.post('/api/webauthn/register-verify', authenticate, async (req, res) => {
  const user = req.user;
  const expectedChallenge = await getChallenge(user.id);

  const verification = await verifyRegistrationResponse({
    response: req.body,
    expectedChallenge,
    expectedOrigin: origin,
    expectedRPID: rpID,
  });

  if (verification.verified) {
    await saveAuthenticator(user.id, verification.registrationInfo);
    res.json({ success: true });
  } else {
    res.status(400).json({ error: 'Verification failed' });
  }
});
